/** Single-activity, entirely native offline edition. All destinations stay inside this process. */
public final class MainActivity extends Activity {
 private GameDatabase db;private PlayerWallet wallet;private ProgressManager progress;private SoundEngine sound;private ThemeManager theme;
 private NativeStageSurface previewStage;private LinearLayout root,body;private TextView status;private GameView gameView;private String gameId,screen="home";private boolean paused=false;private int catalogPage=0;
 @Override public void onCreate(Bundle saved){setTheme(R.style.AppTheme);super.onCreate(saved);db=GameDatabase.create(this);wallet=new PlayerWallet(db);progress=new ProgressManager(db);sound=new SoundEngine(this);theme=new ThemeManager(this);if(saved!=null)gameId=saved.getString("game");if(gameId!=null)openGame(gameId,false);else {String destination=getIntent().getStringExtra("destination");if(destination==null){startActivity(new Intent(this,OpeningActivity.class));finish();}else if(destination.equals("parents")){playroom();parentGate();}else if(destination.equals("privacy"))privacy();else if(destination.equals("friend"))shop();else if(destination.equals("shapes"))category(GameCatalog.Kind.SHAPES,0);else if(destination.equals("puzzles"))category(GameCatalog.Kind.MAZE,0);else playroom();}if(Build.VERSION.SDK_INT>=33)Api33Back.register(this);}
 private void base(String title){if(previewStage!=null){previewStage.pauseStage();previewStage=null;}if(gameView!=null){progress.save(gameView.rules);gameView.pause();gameView=null;}sound.stop();theme=new ThemeManager(this);root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(theme.background);root.setPadding(theme.dp(12),0,theme.dp(12),0);setContentView(root);
  root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(theme.dp(12)+insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),theme.dp(12)+insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});root.requestApplyInsets();getWindow().getDecorView().setSystemUiVisibility(theme.dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
  LinearLayout bar=row();bar.addView(button("Home",()->home()),new LinearLayout.LayoutParams(theme.dp(86),theme.dp(64)));TextView heading=text(title,23,true);heading.setGravity(Gravity.CENTER);bar.addView(heading,new LinearLayout.LayoutParams(0,theme.dp(64),1));root.addView(bar);
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,theme.dp(12),0,theme.dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
 private LinearLayout row(){LinearLayout r=new LinearLayout(this);r.setOrientation(0);r.setGravity(Gravity.CENTER_VERTICAL);return r;}
 private TextView text(String value,int sp,boolean display){TextView t=new TextView(this);t.setText(value);t.setTextColor(theme.text);t.setTextSize(sp);t.setTypeface(theme.font(display));t.setPadding(theme.dp(8),theme.dp(8),theme.dp(8),theme.dp(8));return t;}
 private Button button(String label,Runnable action){Button b=new Button(this);b.setAllCaps(false);b.setText(label);b.setTextSize(17);b.setTypeface(theme.font(false));b.setTextColor(theme.text);b.setElevation(theme.dp(4));b.setMinHeight(theme.dp(64));b.setMinimumHeight(theme.dp(64));b.setBackground(theme.panel(true));b.setPadding(theme.dp(10),theme.dp(8),theme.dp(10),theme.dp(8));b.setOnClickListener(v->{sound.tap();v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);if(!getSharedPreferences("family",0).getBoolean("reduce_motion",false)&&android.provider.Settings.Global.getFloat(getContentResolver(),android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,1)>0){v.animate().scaleX(.96f).scaleY(.96f).setDuration(80).withEndAction(()->v.animate().scaleX(1).scaleY(1).setDuration(150).start()).start();}action.run();});return b;}
 private void addButton(String label,Runnable action){Button b=button(label,action);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,theme.dp(6),0,theme.dp(6));body.addView(b,lp);}
 private void walletLine(){body.addView(text(wallet.stars()+" stars   "+wallet.coins()+" coins\n"+progress.completedCount()+" activities explored",18,false));}
 private void home(){if(getIntent().getBooleanExtra("adventure_return",false)){finish();return;}startActivity(new Intent(this,CreativeActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));finish();}
 private void playroom(){screen="home";gameId=null;base("Little Makers");body.addView(friendPreview(),new LinearLayout.LayoutParams(-1,theme.dp(140)));walletLine();body.addView(text("Choose a place to play. No timer, no hurry.",18,false));addButton("All 9 learning adventures",()->startActivity(new Intent(this,QuestActivity.class)));addButton("My friend - skins and accessories",()->shop());addButton("Parent space",()->parentGate());addButton("Privacy policy",()->privacy());for(GameCatalog.Kind kind:GameCatalog.Kind.values()){GameCatalog.Game example=GameCatalog.at(kind,0);addButton(GameCatalog.sectionTitle(kind)+" - "+GameCatalog.LEVELS_PER_KIND+" games",()->category(kind,0));}}
 private void category(GameCatalog.Kind kind){category(kind,catalogPage);}
 private void category(GameCatalog.Kind kind,int page){catalogPage=Math.max(0,Math.min((GameCatalog.LEVELS_PER_KIND-1)/10,page));screen="catalog";gameId=null;base(GameCatalog.sectionTitle(kind));body.addView(text(GameCatalog.at(kind,0).skill+" - Page "+(catalogPage+1)+" of "+((GameCatalog.LEVELS_PER_KIND+9)/10),18,false));int first=catalogPage*10;for(int i=first;i<first+10;i+=2){LinearLayout r=row();for(int j=i;j<i+2;j++){GameCatalog.Game g=GameCatalog.at(kind,j);Button b=button("Play "+(j+1)+(progress.completed(g.id)?"\nExplored":"\nDiscover"),()->openGame(g.id,false));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,theme.dp(100),1);lp.setMargins(theme.dp(4),theme.dp(5),theme.dp(4),theme.dp(5));r.addView(b,lp);}body.addView(r);}if(catalogPage>0)addButton("Previous page",()->category(kind,catalogPage-1));if(first+10<GameCatalog.LEVELS_PER_KIND)addButton("Next page",()->category(kind,catalogPage+1));}

 private void openGame(String id,boolean fresh){screen="game";catalogPage=GameCatalog.find(id).round/10;gameId=id;base(GameCatalog.find(id).title);GameRules state=new GameRules(GameCatalog.find(id));if(!fresh){try{state.restore(progress.load(id));}catch(IllegalArgumentException invalid){state=new GameRules(GameCatalog.find(id));}}paused=false;LinearLayout controls=row();Button pause=button("Pause",()->{paused=!paused;if(paused)gameView.pause();else gameView.resume();status.setText(paused?"Paused. Take a breath.":gameView.rules.message);});controls.addView(pause,new LinearLayout.LayoutParams(0,theme.dp(64),1));controls.addView(button("Replay",()->openGame(id,true)),new LinearLayout.LayoutParams(0,theme.dp(64),1));body.addView(controls);status=text(state.message,18,false);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);body.addView(status);
  gameView=new GameView(this,state,theme,sound,wallet,new GameView.Listener(){public void changed(GameRules s){progress.save(s);status.setText(s.message);}public void completed(GameRules s){boolean first=progress.complete(s);status.setText(first?"You explored it! +1 star and +"+s.game.rewardCoins()+" coins.":"You explored it again! Your first-clear reward is saved.");}});HorizontalScrollView canvasScroll=new HorizontalScrollView(this);canvasScroll.setFillViewport(true);int canvasWidth=Math.max(theme.dp(320),getResources().getDisplayMetrics().widthPixels-theme.dp(24));FrameLayout stageFrame=new FrameLayout(this);stageFrame.setMinimumHeight(Math.round(canvasWidth*1000f/640));
  if(((android.app.ActivityManager)getSystemService(ACTIVITY_SERVICE)).getDeviceConfigurationInfo().reqGlEsVersion>=0x20000){final GameView target=gameView;final NativeStageSurface[]holder={null};NativeStageSurface stage=new NativeStageSurface(this,theme.dark,()->{target.stage(null);if(holder[0]!=null){holder[0].pauseStage();holder[0].setVisibility(View.GONE);}});holder[0]=stage;stageFrame.addView(stage,new FrameLayout.LayoutParams(-1,-1));gameView.stage(stage);}
  stageFrame.addView(gameView,new FrameLayout.LayoutParams(-1,-1));canvasScroll.addView(stageFrame,new ViewGroup.LayoutParams(canvasWidth,Math.round(canvasWidth*1000f/640)));body.addView(canvasScroll,new LinearLayout.LayoutParams(-1,-2));addButton("More games here",()->category(GameCatalog.find(id).kind));}
 private void shop(){screen="shop";gameId=null;base("My friend");body.addView(text("Coins are earned by play only. They have no cash value. No money purchases.",17,false));body.addView(friendPreview(),new LinearLayout.LayoutParams(-1,theme.dp(140)));walletLine();for(PlayerWallet.Item item:PlayerWallet.SHOP){addButton(item.name+" - "+(wallet.owns(item.id)?"Equip":item.cost+" coins"),()->{String result=wallet.purchase(item.id);shop();body.addView(text(result,18,false),0);});}}
 private void parentGate(){String stored=getSharedPreferences("family",0).getString("pin_hash","");boolean setup=stored.isEmpty();LinearLayout form=new LinearLayout(this);form.setOrientation(1);EditText input=new EditText(this),confirmation=new EditText(this);for(EditText e:new EditText[]{input,confirmation}){e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(6)});e.setTextColor(theme.text);e.setHintTextColor(theme.text);e.setTextSize(22);e.setMinHeight(theme.dp(64));form.addView(e);}input.setHint(setup?"Create six-digit parent PIN":"Parent PIN");confirmation.setHint("Repeat parent PIN");confirmation.setVisibility(setup?View.VISIBLE:View.GONE);
  AlertDialog d=new AlertDialog.Builder(this).setTitle(setup?"Parent setup":"Parent space").setMessage("Ask a grown-up. PIN stays on this device.").setView(form).setPositiveButton("Continue",null).setNegativeButton("Back",null).create();d.setOnShowListener(v->{d.getWindow().setBackgroundDrawable(theme.panel(false));styleDialog(d);d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(b->{String pin=input.getText().toString();if(!pin.matches("[0-9]{6}")||(setup&&!pin.equals(confirmation.getText().toString()))){input.setError("Enter matching six-digit PINs.");return;}String salt=getSharedPreferences("family",0).getString("pin_salt","");if(setup){byte[]bytes=new byte[16];new SecureRandom().nextBytes(bytes);salt=hex(bytes);getSharedPreferences("family",0).edit().putString("pin_salt",salt).putString("pin_hash",hash(salt+pin)).apply();}else if(!MessageDigest.isEqual(hash(salt+pin).getBytes(java.nio.charset.StandardCharsets.UTF_8),stored.getBytes(java.nio.charset.StandardCharsets.UTF_8))){input.setError("Check your PIN with a grown-up.");return;}d.dismiss();parents();});});d.show();}
 private void styleDialog(AlertDialog d){View decor=d.getWindow().getDecorView();styleText(decor);}
 private void styleText(View v){if(v instanceof TextView){TextView t=(TextView)v;t.setTextColor(theme.text);t.setTypeface(theme.font(false));}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)styleText(((ViewGroup)v).getChildAt(i));}
 private static String hex(byte[]data){StringBuilder b=new StringBuilder();for(byte x:data)b.append(String.format(Locale.ROOT,"%02x",x&255));return b.toString();}
 private static String hash(String value){try{return hex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private void parents(){screen="parent";gameId=null;base("Parent space");walletLine();body.addView(text("1,200 modules across 20 original mechanics. First completion gives one star and fixed coins. Replay is always free. All progress stays on this device.",17,false));for(String mode:new String[]{"light","dark","system"})addButton("Theme: "+mode,()->{getSharedPreferences("family",0).edit().putString("theme",mode).apply();parents();});addButton("Sound: "+(getSharedPreferences("family",0).getBoolean("sound",true)?"on":"off"),()->{sound.setEnabled(!getSharedPreferences("family",0).getBoolean("sound",true));parents();});addButton("Reduced motion: "+(getSharedPreferences("family",0).getBoolean("reduce_motion",false)?"on":"off"),()->{getSharedPreferences("family",0).edit().putBoolean("reduce_motion",!getSharedPreferences("family",0).getBoolean("reduce_motion",false)).apply();parents();});addButton("Privacy policy",()->privacy());addButton("Reset local progress",()->resetDialog());body.addView(text("Take breaks together. The parent PIN is a local settings barrier, not proof of parental consent. It is not a child account. This native edition does not import the web edition profile.",17,false));}
 @Override protected void onPause(){if(previewStage!=null)previewStage.pauseStage();if(gameView!=null){progress.save(gameView.rules);gameView.pause();}sound.stop();if(screen.equals("parent"))home();super.onPause();}
 @Override protected void onResume(){super.onResume();if(previewStage!=null)previewStage.resumeStage();if(gameView!=null&&!paused)gameView.resume();}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);if(gameId!=null)out.putString("game",gameId);}
 private void navigateBack(){switch(NavigationPolicy.back(screen,gameId)){case CATALOG:category(GameCatalog.find(gameId).kind);break;case HOME:home();break;case EXIT:finish();break;}}
 @Override public void onBackPressed(){navigateBack();}
 private static final class Api33Back {static void register(MainActivity a){a.getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,a::navigateBack);}}
 private String policyText(){try(java.io.InputStream in=getResources().openRawResource(R.raw.privacy);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream()){byte[]b=new byte[4096];int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);return new String(bytes.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);}catch(java.io.IOException e){return "Privacy policy could not be loaded. Please restart the app.";}}
 private void privacy(){screen="privacy";gameId=null;base("Privacy policy");TextView policy=text(policyText(),17,false);policy.setTextIsSelectable(true);body.addView(policy);addButton("Home",()->home());}
 private void clearCreativeFiles(java.io.File file){if(file.isDirectory()){java.io.File[] children=file.listFiles();if(children!=null)for(java.io.File child:children)clearCreativeFiles(child);}if(file.exists()&&!file.delete())throw new IllegalStateException("Could not remove creative data");}
 private void resetDialog(){EditText confirmation=new EditText(this);confirmation.setHint("Type RESET");confirmation.setTextColor(theme.text);confirmation.setHintTextColor(theme.text);confirmation.setMinHeight(theme.dp(64));AlertDialog d=new AlertDialog.Builder(this).setTitle("Reset local progress?").setMessage("This permanently removes saved games, drawings, kept creations, stars, coins and equipped items on this device. Your theme, sound and parent PIN stay. Type RESET to continue.").setView(confirmation).setNegativeButton("Keep progress",null).setPositiveButton("Reset",null).create();d.setOnShowListener(v->{d.getWindow().setBackgroundDrawable(theme.panel(false));styleDialog(d);d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(b->{if(!screen.equals("parent")){d.dismiss();return;}if(!"RESET".equals(confirmation.getText().toString())){confirmation.setError("Type RESET to confirm.");return;}db.resetLocalProgress();clearCreativeFiles(new java.io.File(getFilesDir(),"drafts"));clearCreativeFiles(new java.io.File(getFilesDir(),"creations"));getSharedPreferences("creative",0).edit().clear().apply();getSharedPreferences("adventure",0).edit().clear().apply();getSharedPreferences("learning_quests",0).edit().clear().apply();getSharedPreferences("explorer_studios",0).edit().clear().apply();getSharedPreferences("family",0).edit().putLong("quest_reset_generation",System.currentTimeMillis()).apply();d.dismiss();parents();body.addView(text("Local progress was reset. Settings and PIN were kept.",17,false),0);});});d.show();}
 @Override public void onDestroy(){sound.stop();db.close();super.onDestroy();}
 private View friendPreview(){
  if(((android.app.ActivityManager)getSystemService(ACTIVITY_SERVICE)).getDeviceConfigurationInfo().reqGlEsVersion<0x20000)return new FriendView(this);
  FrameLayout frame=new FrameLayout(this);final NativeStageSurface[]holder={null};previewStage=new NativeStageSurface(this,theme.dark,()->{if(holder[0]!=null){holder[0].pauseStage();frame.removeView(holder[0]);frame.addView(new FriendView(this),new FrameLayout.LayoutParams(-1,-1));}});holder[0]=previewStage;String a=wallet.equipped("accessory");int accessory=a.equals("hat")?1:a.equals("bow")?2:a.equals("star")?3:0;java.util.List<SceneFrame.Node>nodes=java.util.Arrays.asList(new SceneFrame.Node(SceneFrame.CHARACTER,320,160,115,115,40,wallet.skinColor(),accessory,true));previewStage.submit(new SceneFrame(nodes,theme.background,250,"showcase",false));frame.addView(previewStage,new FrameLayout.LayoutParams(-1,-1));frame.setContentDescription("Your three-dimensional friend wearing your chosen skin and accessory");return frame;
 }
 private final class FriendView extends View {private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);FriendView(Context c){super(c);setContentDescription("Your original Little Makers friend");}protected void onDraw(Canvas c){boolean move=!getSharedPreferences("family",0).getBoolean("reduce_motion",false)&&android.provider.Settings.Global.getFloat(getContentResolver(),android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,1)>0;float y=getHeight()/2f+(move?(float)Math.sin(SystemClock.uptimeMillis()/650.)*theme.dp(5):0);Artwork.buddy(c,getWidth()/2f,y,theme.dp(100),wallet.skinColor(),wallet.equipped("accessory"),p);if(move&&isShown()&&hasWindowFocus())postInvalidateDelayed(40);}}
}
